insert into kafaa_smr_deltas (id, role_id, tech_id, rank, path_only, dims, changes_en, changes_ar, stays_en, stays_ar, skills, training, concept_role_ids, sources, benchmark_ids, status, listed, version, as_of, sort, updated_by, updated_at) values
('smrd:fire-protection:tech-bwr', 'fire-protection', 'tech-bwr', 2, false, '[{"dim":"multi_module","change":"adapts","text_en":"A fleet of small units means several smaller reactors to run and maintain rather than a few large ones. Emergency plans and drills cover several smaller units.","text_ar":"يعني أسطول من الوحدات الصغيرة تشغيل وصيانة عدد من المفاعلات الأصغر بدلاً من عدد قليل من المفاعلات الكبيرة. تغطي خطط الطوارئ والتمارين عدة وحدات أصغر."},{"dim":"passive_safety","change":"new","text_en":"Small reactor designs put more weight on passive cooling that works for a period without AC power or operator action. Longer coping times change the timeline of an emergency response.","text_ar":"تعطي تصاميم المفاعلات الصغيرة وزناً أكبر للتبريد الخامل الذي يعمل لفترة دون كهرباء متناوبة أو تدخل من المشغلين. تغيّر فترات التحمل الأطول الجدول الزمني للاستجابة للطوارئ."},{"dim":"digital_ic","change":"adapts","text_en":"A different digital control platform and alarm philosophy from the APR-1400 digital I&C you know. Remote monitoring feeds the emergency organisation.","text_ar":"منصة تحكم رقمية وفلسفة إنذارات تختلفان عن الأجهزة والتحكم الرقمية في APR-1400 التي تعرفها. تغذي المراقبة عن بعد منظمة الطوارئ."},{"dim":"systems","change":"new","text_en":"A boiling water reactor makes steam in the reactor itself, so plant systems, water chemistry and radiation zones differ from Barakah''s two-loop APR-1400 units. New industrial hazards from different coolants and materials.","text_ar":"يولّد مفاعل الماء المغلي البخار داخل المفاعل نفسه، فتختلف أنظمة المحطة وكيمياء الماء ومناطق الإشعاع عن وحدات APR-1400 ذات الدائرتين في براكة. مخاطر صناعية جديدة من المبردات والمواد المختلفة."}]'::jsonb, 'Small boiling water reactor: the biggest shifts for this role are passive safety and plant systems, coolant and fuel; multi-module operation and digital I&C adapt. Planning assumption; no deployment decision implied.', 'مفاعل الماء المغلي الصغير: أكبر التحولات لهذا الدور في السلامة الخاملة، وأنظمة المحطة والمبرد والوقود، بينما يتكيف كل من التشغيل متعدد الوحدات، والأجهزة والتحكم الرقمية. افتراض تخطيطي، ولا يعني ذلك أي قرار بالنشر.', 'Hazard identification, permits, drills and the emergency organisation''s roles stay the same.', 'يبقى تحديد المخاطر والتصاريح والتمارين وأدوار منظمة الطوارئ كما هي.', '[{"skill_id":"sk-fs-adv-smr","level":1},{"skill_id":"sk-fs-adv-multimodule","level":1},{"skill_id":"sk-fs-adv-passive","level":1},{"skill_id":"sk-fs-dp-dic","level":1}]'::jsonb, '[{"kind":"microcred","ref":"MC-SMR-FOUND"},{"kind":"course","ref":"c-fs-smr"},{"kind":"pathway","ref":"pw-adv-smr-l1"},{"kind":"course","ref":"c-fs-passive"},{"kind":"pathway","ref":"pw-adv-passive-l1"},{"kind":"pathway","ref":"pw-dp-dic-l1"},{"kind":"pathway","ref":"pw-adv-multimodule-l1"},{"kind":"lane","ref":"lane-advanced"}]'::jsonb, '{}'::text[], '[{"id":"ans-smr-wf-2025","label":"ANS Nuclear Newswire · Education and training to support Canadian nuclear workforce development (26 Nov 2025)","url":"https://www.ans.org/news/2025-11-26/article-7471/education-and-training-to-support-canadian-nuclear-workforce-development/","as_of":"2026-10-10"},{"id":"iaea-ng-t-3-10","label":"IAEA NG-T-3.10 · Workforce Planning for New Nuclear Power Programmes (2011)","url":"https://www-pub.iaea.org/MTCD/Publications/PDF/Pub1477_web.pdf","as_of":"2026-10-10"},{"id":"gevh-smr-centre-2025","label":"GE Vernova · GE Vernova Hitachi SMR engineering and service centre, Ontario (June 2025)","url":"https://www.gevernova.com/news/press-releases/ge-vernova-hitachi-nuclear-energy-canada-small-modular-reactor-engineering-service-centre-ontario","as_of":"2026-10-10"}]'::jsonb, array['SMR-WF','IAEA-WFP']::text[], 'published', true, 1, '2026-10-11', 69, 'p-training-mgr', '2026-10-11T08:00:00Z'),
('smrd:fire-protection:tech-msr', 'fire-protection', 'tech-msr', 3, false, '[{"dim":"multi_module","change":"adapts","text_en":"Modular plant concepts with several units. Emergency plans and drills cover several smaller units.","text_ar":"مفاهيم محطات معيارية بعدة وحدات. تغطي خطط الطوارئ والتمارين عدة وحدات أصغر."},{"dim":"passive_safety","change":"new","text_en":"Molten salt concepts rely on passive features of the salt and the design to remove heat. Longer coping times change the timeline of an emergency response.","text_ar":"تعتمد مفاهيم الأملاح المنصهرة على الخصائص الخاملة للملح والتصميم لإزالة الحرارة. تغيّر فترات التحمل الأطول الجدول الزمني للاستجابة للطوارئ."},{"dim":"digital_ic","change":"adapts","text_en":"Instrumentation and sampling designed for hot salt systems. Remote monitoring feeds the emergency organisation.","text_ar":"أجهزة وأخذ عينات مصممة لأنظمة الأملاح الساخنة. تغذي المراقبة عن بعد منظمة الطوارئ."},{"dim":"systems","change":"new","text_en":"Salt chemistry and materials replace water chemistry. New industrial hazards from different coolants and materials.","text_ar":"تحل كيمياء الأملاح وموادها محل كيمياء الماء. مخاطر صناعية جديدة من المبردات والمواد المختلفة."}]'::jsonb, 'Molten salt: the biggest shifts for this role are passive safety and plant systems, coolant and fuel; multi-module operation and digital I&C adapt. Planning assumption; no deployment decision implied.', 'مفاعلات الأملاح المنصهرة: أكبر التحولات لهذا الدور في السلامة الخاملة، وأنظمة المحطة والمبرد والوقود، بينما يتكيف كل من التشغيل متعدد الوحدات، والأجهزة والتحكم الرقمية. افتراض تخطيطي، ولا يعني ذلك أي قرار بالنشر.', 'Hazard identification, permits, drills and the emergency organisation''s roles stay the same.', 'يبقى تحديد المخاطر والتصاريح والتمارين وأدوار منظمة الطوارئ كما هي.', '[{"skill_id":"sk-fs-adv-smr","level":1},{"skill_id":"sk-fs-adv-multimodule","level":1},{"skill_id":"sk-fs-adv-passive","level":1},{"skill_id":"sk-fs-dp-dic","level":1}]'::jsonb, '[{"kind":"microcred","ref":"MC-SMR-FOUND"},{"kind":"course","ref":"c-fs-smr"},{"kind":"pathway","ref":"pw-adv-smr-l1"},{"kind":"course","ref":"c-fs-passive"},{"kind":"pathway","ref":"pw-adv-passive-l1"},{"kind":"pathway","ref":"pw-dp-dic-l1"},{"kind":"pathway","ref":"pw-adv-multimodule-l1"},{"kind":"lane","ref":"lane-advanced"}]'::jsonb, '{}'::text[], '[{"id":"ans-smr-wf-2025","label":"ANS Nuclear Newswire · Education and training to support Canadian nuclear workforce development (26 Nov 2025)","url":"https://www.ans.org/news/2025-11-26/article-7471/education-and-training-to-support-canadian-nuclear-workforce-development/","as_of":"2026-10-10"},{"id":"iaea-ng-t-3-10","label":"IAEA NG-T-3.10 · Workforce Planning for New Nuclear Power Programmes (2011)","url":"https://www-pub.iaea.org/MTCD/Publications/PDF/Pub1477_web.pdf","as_of":"2026-10-10"}]'::jsonb, array['SMR-WF','IAEA-WFP']::text[], 'published', true, 1, '2026-10-11', 70, 'p-training-mgr', '2026-10-11T08:00:00Z'),
('smrd:emergency-preparedness-coordinator:tech-micro', 'emergency-preparedness-coordinator', 'tech-micro', 1, false, '[{"dim":"multi_module","change":"adapts","text_en":"Many small transportable units rather than one plant. Emergency plans and drills cover several smaller units.","text_ar":"وحدات صغيرة كثيرة قابلة للنقل بدلاً من محطة واحدة. تغطي خطط الطوارئ والتمارين عدة وحدات أصغر."},{"dim":"passive_safety","change":"new","text_en":"Microreactor concepts are designed to cool themselves passively for long periods. Longer coping times change the timeline of an emergency response.","text_ar":"صُممت مفاهيم المفاعلات المتناهية الصغر لتبريد نفسها بطريقة خاملة لفترات طويلة. تغيّر فترات التحمل الأطول الجدول الزمني للاستجابة للطوارئ."},{"dim":"digital_ic","change":"adapts","text_en":"Remote and autonomous operation concepts: monitoring from a distance rather than from a local control room. Remote monitoring feeds the emergency organisation.","text_ar":"مفاهيم التشغيل عن بعد والتشغيل الذاتي: المراقبة من بعيد بدلاً من غرفة تحكم محلية. تغذي المراقبة عن بعد منظمة الطوارئ."},{"dim":"systems","change":"adapts","text_en":"Compact designs with their own coolant and fuel choices. New industrial hazards from different coolants and materials.","text_ar":"تصاميم مدمجة لها خياراتها الخاصة من المبرد والوقود. مخاطر صناعية جديدة من المبردات والمواد المختلفة."}]'::jsonb, 'Microreactors: the biggest shifts for this role are passive safety; multi-module operation, digital I&C and plant systems, coolant and fuel adapt. Planning assumption; no deployment decision implied.', 'المفاعلات المتناهية الصغر: أكبر التحولات لهذا الدور في السلامة الخاملة، بينما يتكيف كل من التشغيل متعدد الوحدات، والأجهزة والتحكم الرقمية، وأنظمة المحطة والمبرد والوقود. افتراض تخطيطي، ولا يعني ذلك أي قرار بالنشر.', 'Hazard identification, permits, drills and the emergency organisation''s roles stay the same.', 'يبقى تحديد المخاطر والتصاريح والتمارين وأدوار منظمة الطوارئ كما هي.', '[{"skill_id":"sk-fs-adv-smr","level":1},{"skill_id":"sk-fs-adv-multimodule","level":1},{"skill_id":"sk-fs-adv-passive","level":1},{"skill_id":"sk-fs-dp-dic","level":1},{"skill_id":"sk-fs-adv-micro","level":1}]'::jsonb, '[{"kind":"microcred","ref":"MC-SMR-FOUND"},{"kind":"course","ref":"c-fs-smr"},{"kind":"pathway","ref":"pw-adv-smr-l1"},{"kind":"course","ref":"c-fs-passive"},{"kind":"pathway","ref":"pw-adv-passive-l1"},{"kind":"pathway","ref":"pw-adv-micro-l1"},{"kind":"course","ref":"c-fs-remote"},{"kind":"pathway","ref":"pw-dp-dic-l1"}]'::jsonb, '{}'::text[], '[{"id":"ans-smr-wf-2025","label":"ANS Nuclear Newswire · Education and training to support Canadian nuclear workforce development (26 Nov 2025)","url":"https://www.ans.org/news/2025-11-26/article-7471/education-and-training-to-support-canadian-nuclear-workforce-development/","as_of":"2026-10-10"},{"id":"iaea-ng-t-3-10","label":"IAEA NG-T-3.10 · Workforce Planning for New Nuclear Power Programmes (2011)","url":"https://www-pub.iaea.org/MTCD/Publications/PDF/Pub1477_web.pdf","as_of":"2026-10-10"}]'::jsonb, array['SMR-WF','IAEA-WFP']::text[], 'published', true, 1, '2026-10-11', 71, 'p-training-mgr', '2026-10-11T08:00:00Z'),
('smrd:emergency-preparedness-coordinator:tech-bwr', 'emergency-preparedness-coordinator', 'tech-bwr', 2, false, '[{"dim":"multi_module","change":"adapts","text_en":"A fleet of small units means several smaller reactors to run and maintain rather than a few large ones. Emergency plans and drills cover several smaller units.","text_ar":"يعني أسطول من الوحدات الصغيرة تشغيل وصيانة عدد من المفاعلات الأصغر بدلاً من عدد قليل من المفاعلات الكبيرة. تغطي خطط الطوارئ والتمارين عدة وحدات أصغر."},{"dim":"passive_safety","change":"new","text_en":"Small reactor designs put more weight on passive cooling that works for a period without AC power or operator action. Longer coping times change the timeline of an emergency response.","text_ar":"تعطي تصاميم المفاعلات الصغيرة وزناً أكبر للتبريد الخامل الذي يعمل لفترة دون كهرباء متناوبة أو تدخل من المشغلين. تغيّر فترات التحمل الأطول الجدول الزمني للاستجابة للطوارئ."},{"dim":"digital_ic","change":"adapts","text_en":"A different digital control platform and alarm philosophy from the APR-1400 digital I&C you know. Remote monitoring feeds the emergency organisation.","text_ar":"منصة تحكم رقمية وفلسفة إنذارات تختلفان عن الأجهزة والتحكم الرقمية في APR-1400 التي تعرفها. تغذي المراقبة عن بعد منظمة الطوارئ."},{"dim":"systems","change":"new","text_en":"A boiling water reactor makes steam in the reactor itself, so plant systems, water chemistry and radiation zones differ from Barakah''s two-loop APR-1400 units. New industrial hazards from different coolants and materials.","text_ar":"يولّد مفاعل الماء المغلي البخار داخل المفاعل نفسه، فتختلف أنظمة المحطة وكيمياء الماء ومناطق الإشعاع عن وحدات APR-1400 ذات الدائرتين في براكة. مخاطر صناعية جديدة من المبردات والمواد المختلفة."}]'::jsonb, 'Small boiling water reactor: the biggest shifts for this role are passive safety and plant systems, coolant and fuel; multi-module operation and digital I&C adapt. Planning assumption; no deployment decision implied.', 'مفاعل الماء المغلي الصغير: أكبر التحولات لهذا الدور في السلامة الخاملة، وأنظمة المحطة والمبرد والوقود، بينما يتكيف كل من التشغيل متعدد الوحدات، والأجهزة والتحكم الرقمية. افتراض تخطيطي، ولا يعني ذلك أي قرار بالنشر.', 'Hazard identification, permits, drills and the emergency organisation''s roles stay the same.', 'يبقى تحديد المخاطر والتصاريح والتمارين وأدوار منظمة الطوارئ كما هي.', '[{"skill_id":"sk-fs-adv-smr","level":1},{"skill_id":"sk-fs-adv-multimodule","level":1},{"skill_id":"sk-fs-adv-passive","level":1},{"skill_id":"sk-fs-dp-dic","level":1}]'::jsonb, '[{"kind":"microcred","ref":"MC-SMR-FOUND"},{"kind":"course","ref":"c-fs-smr"},{"kind":"pathway","ref":"pw-adv-smr-l1"},{"kind":"course","ref":"c-fs-passive"},{"kind":"pathway","ref":"pw-adv-passive-l1"},{"kind":"pathway","ref":"pw-dp-dic-l1"},{"kind":"pathway","ref":"pw-adv-multimodule-l1"},{"kind":"lane","ref":"lane-advanced"}]'::jsonb, '{}'::text[], '[{"id":"ans-smr-wf-2025","label":"ANS Nuclear Newswire · Education and training to support Canadian nuclear workforce development (26 Nov 2025)","url":"https://www.ans.org/news/2025-11-26/article-7471/education-and-training-to-support-canadian-nuclear-workforce-development/","as_of":"2026-10-10"},{"id":"iaea-ng-t-3-10","label":"IAEA NG-T-3.10 · Workforce Planning for New Nuclear Power Programmes (2011)","url":"https://www-pub.iaea.org/MTCD/Publications/PDF/Pub1477_web.pdf","as_of":"2026-10-10"},{"id":"gevh-smr-centre-2025","label":"GE Vernova · GE Vernova Hitachi SMR engineering and service centre, Ontario (June 2025)","url":"https://www.gevernova.com/news/press-releases/ge-vernova-hitachi-nuclear-energy-canada-small-modular-reactor-engineering-service-centre-ontario","as_of":"2026-10-10"}]'::jsonb, array['SMR-WF','IAEA-WFP']::text[], 'published', true, 1, '2026-10-11', 72, 'p-training-mgr', '2026-10-11T08:00:00Z'),
('smrd:emergency-preparedness-coordinator:tech-htgr', 'emergency-preparedness-coordinator', 'tech-htgr', 3, false, '[{"dim":"multi_module","change":"adapts","text_en":"Several smaller reactor modules may share one plant and one control room. Emergency plans and drills cover several smaller units.","text_ar":"قد تتشارك عدة وحدات مفاعل أصغر محطة واحدة وغرفة تحكم واحدة. تغطي خطط الطوارئ والتمارين عدة وحدات أصغر."},{"dim":"passive_safety","change":"new","text_en":"Gas-cooled designs aim to remove decay heat passively, relying on fuel and materials that tolerate high temperatures. Longer coping times change the timeline of an emergency response.","text_ar":"تسعى التصاميم المبرّدة بالغاز إلى إزالة حرارة الاضمحلال بطريقة خاملة، معتمدة على وقود ومواد تتحمل درجات حرارة عالية. تغيّر فترات التحمل الأطول الجدول الزمني للاستجابة للطوارئ."},{"dim":"digital_ic","change":"adapts","text_en":"New digital instrumentation for gas coolant and high-temperature systems. Remote monitoring feeds the emergency organisation.","text_ar":"أجهزة رقمية جديدة لأنظمة التبريد بالغاز والأنظمة عالية الحرارة. تغذي المراقبة عن بعد منظمة الطوارئ."},{"dim":"systems","change":"new","text_en":"Gas coolant, a different fuel form and high-temperature heat that can also serve industrial processes. New industrial hazards from different coolants and materials.","text_ar":"تبريد بالغاز وشكل وقود مختلف وحرارة عالية يمكن أن تخدم العمليات الصناعية أيضاً. مخاطر صناعية جديدة من المبردات والمواد المختلفة."}]'::jsonb, 'High-temperature gas-cooled: the biggest shifts for this role are passive safety and plant systems, coolant and fuel; multi-module operation and digital I&C adapt. Planning assumption; no deployment decision implied.', 'المفاعلات عالية الحرارة المبرّدة بالغاز: أكبر التحولات لهذا الدور في السلامة الخاملة، وأنظمة المحطة والمبرد والوقود، بينما يتكيف كل من التشغيل متعدد الوحدات، والأجهزة والتحكم الرقمية. افتراض تخطيطي، ولا يعني ذلك أي قرار بالنشر.', 'Hazard identification, permits, drills and the emergency organisation''s roles stay the same.', 'يبقى تحديد المخاطر والتصاريح والتمارين وأدوار منظمة الطوارئ كما هي.', '[{"skill_id":"sk-fs-adv-smr","level":1},{"skill_id":"sk-fs-adv-multimodule","level":1},{"skill_id":"sk-fs-adv-passive","level":1},{"skill_id":"sk-fs-dp-dic","level":1}]'::jsonb, '[{"kind":"microcred","ref":"MC-SMR-FOUND"},{"kind":"course","ref":"c-fs-smr"},{"kind":"pathway","ref":"pw-adv-smr-l1"},{"kind":"course","ref":"c-fs-passive"},{"kind":"pathway","ref":"pw-adv-passive-l1"},{"kind":"pathway","ref":"pw-dp-dic-l1"},{"kind":"pathway","ref":"pw-adv-multimodule-l1"},{"kind":"lane","ref":"lane-hydrogen"}]'::jsonb, '{}'::text[], '[{"id":"ans-smr-wf-2025","label":"ANS Nuclear Newswire · Education and training to support Canadian nuclear workforce development (26 Nov 2025)","url":"https://www.ans.org/news/2025-11-26/article-7471/education-and-training-to-support-canadian-nuclear-workforce-development/","as_of":"2026-10-10"},{"id":"iaea-ng-t-3-10","label":"IAEA NG-T-3.10 · Workforce Planning for New Nuclear Power Programmes (2011)","url":"https://www-pub.iaea.org/MTCD/Publications/PDF/Pub1477_web.pdf","as_of":"2026-10-10"}]'::jsonb, array['SMR-WF','IAEA-WFP']::text[], 'published', true, 1, '2026-10-11', 73, 'p-training-mgr', '2026-10-11T08:00:00Z'),
('smrd:security-officer:tech-bwr', 'security-officer', 'tech-bwr', 1, true, '[{"dim":"systems","change":"adapts","text_en":"Any future fleet would bring its own arrangements, designed and managed outside Kafa''a; this overlay stays at career-path level.","text_ar":"سيأتي أي أسطول مستقبلي بترتيباته الخاصة التي تُصمَّم وتُدار خارج كفاءة؛ وتبقى هذه الطبقة على مستوى المسار المهني."}]'::jsonb, 'Small boiling water reactor: career-path view only. Security, safeguards and cyber arrangements for any future fleet are designed and managed outside Kafa''a. Planning assumption; no deployment decision implied.', 'مفاعل الماء المغلي الصغير: عرض على مستوى المسار المهني فقط. تُصمَّم ترتيبات الأمن والضمانات والأمن السيبراني لأي أسطول مستقبلي وتُدار خارج كفاءة. افتراض تخطيطي، ولا يعني ذلك أي قرار بالنشر.', 'Your qualification shows only as qualified or not qualified; no security detail is shown here.', 'يظهر تأهيلك فقط بصفة مؤهَّل أو غير مؤهَّل، ولا تُعرض هنا أي تفاصيل أمنية.', '[]'::jsonb, '[{"kind":"course","ref":"c-fs-smr"},{"kind":"lane","ref":"lane-advanced"}]'::jsonb, '{}'::text[], '[{"id":"ans-smr-wf-2025","label":"ANS Nuclear Newswire · Education and training to support Canadian nuclear workforce development (26 Nov 2025)","url":"https://www.ans.org/news/2025-11-26/article-7471/education-and-training-to-support-canadian-nuclear-workforce-development/","as_of":"2026-10-10"},{"id":"iaea-ng-t-3-10","label":"IAEA NG-T-3.10 · Workforce Planning for New Nuclear Power Programmes (2011)","url":"https://www-pub.iaea.org/MTCD/Publications/PDF/Pub1477_web.pdf","as_of":"2026-10-10"},{"id":"gevh-smr-centre-2025","label":"GE Vernova · GE Vernova Hitachi SMR engineering and service centre, Ontario (June 2025)","url":"https://www.gevernova.com/news/press-releases/ge-vernova-hitachi-nuclear-energy-canada-small-modular-reactor-engineering-service-centre-ontario","as_of":"2026-10-10"}]'::jsonb, array['SMR-WF','IAEA-WFP']::text[], 'published', true, 1, '2026-10-11', 74, 'p-training-mgr', '2026-10-11T08:00:00Z'),
('smrd:security-officer:tech-micro', 'security-officer', 'tech-micro', 2, true, '[{"dim":"systems","change":"adapts","text_en":"Any future fleet would bring its own arrangements, designed and managed outside Kafa''a; this overlay stays at career-path level.","text_ar":"سيأتي أي أسطول مستقبلي بترتيباته الخاصة التي تُصمَّم وتُدار خارج كفاءة؛ وتبقى هذه الطبقة على مستوى المسار المهني."}]'::jsonb, 'Microreactors: career-path view only. Security, safeguards and cyber arrangements for any future fleet are designed and managed outside Kafa''a. Planning assumption; no deployment decision implied.', 'المفاعلات المتناهية الصغر: عرض على مستوى المسار المهني فقط. تُصمَّم ترتيبات الأمن والضمانات والأمن السيبراني لأي أسطول مستقبلي وتُدار خارج كفاءة. افتراض تخطيطي، ولا يعني ذلك أي قرار بالنشر.', 'Your qualification shows only as qualified or not qualified; no security detail is shown here.', 'يظهر تأهيلك فقط بصفة مؤهَّل أو غير مؤهَّل، ولا تُعرض هنا أي تفاصيل أمنية.', '[]'::jsonb, '[{"kind":"course","ref":"c-fs-smr"},{"kind":"lane","ref":"lane-advanced"}]'::jsonb, '{}'::text[], '[{"id":"ans-smr-wf-2025","label":"ANS Nuclear Newswire · Education and training to support Canadian nuclear workforce development (26 Nov 2025)","url":"https://www.ans.org/news/2025-11-26/article-7471/education-and-training-to-support-canadian-nuclear-workforce-development/","as_of":"2026-10-10"},{"id":"iaea-ng-t-3-10","label":"IAEA NG-T-3.10 · Workforce Planning for New Nuclear Power Programmes (2011)","url":"https://www-pub.iaea.org/MTCD/Publications/PDF/Pub1477_web.pdf","as_of":"2026-10-10"}]'::jsonb, array['SMR-WF','IAEA-WFP']::text[], 'published', true, 1, '2026-10-11', 75, 'p-training-mgr', '2026-10-11T08:00:00Z'),
('smrd:security-officer:tech-intl', 'security-officer', 'tech-intl', 3, true, '[{"dim":"systems","change":"adapts","text_en":"Any future fleet would bring its own arrangements, designed and managed outside Kafa''a; this overlay stays at career-path level.","text_ar":"سيأتي أي أسطول مستقبلي بترتيباته الخاصة التي تُصمَّم وتُدار خارج كفاءة؛ وتبقى هذه الطبقة على مستوى المسار المهني."}]'::jsonb, 'International projects: career-path view only. Security, safeguards and cyber arrangements for any future fleet are designed and managed outside Kafa''a. Planning assumption; no deployment decision implied.', 'المشاريع الدولية: عرض على مستوى المسار المهني فقط. تُصمَّم ترتيبات الأمن والضمانات والأمن السيبراني لأي أسطول مستقبلي وتُدار خارج كفاءة. افتراض تخطيطي، ولا يعني ذلك أي قرار بالنشر.', 'Your qualification shows only as qualified or not qualified; no security detail is shown here.', 'يظهر تأهيلك فقط بصفة مؤهَّل أو غير مؤهَّل، ولا تُعرض هنا أي تفاصيل أمنية.', '[]'::jsonb, '[{"kind":"course","ref":"c-fs-smr"},{"kind":"lane","ref":"lane-advanced"}]'::jsonb, '{}'::text[], '[{"id":"ans-smr-wf-2025","label":"ANS Nuclear Newswire · Education and training to support Canadian nuclear workforce development (26 Nov 2025)","url":"https://www.ans.org/news/2025-11-26/article-7471/education-and-training-to-support-canadian-nuclear-workforce-development/","as_of":"2026-10-10"},{"id":"iaea-ng-t-3-10","label":"IAEA NG-T-3.10 · Workforce Planning for New Nuclear Power Programmes (2011)","url":"https://www-pub.iaea.org/MTCD/Publications/PDF/Pub1477_web.pdf","as_of":"2026-10-10"},{"id":"nucleareurope-match","label":"nucleareurope · MATCH programme: a tool for nuclear capacity building in France","url":"https://www.nucleareurope.eu/blog/highlight-of-the-month/match-program-a-tool-for-nuclear-capacity-building-in-france/","as_of":"2026-10-10"}]'::jsonb, array['SMR-WF','IAEA-WFP']::text[], 'published', true, 1, '2026-10-11', 76, 'p-training-mgr', '2026-10-11T08:00:00Z'),
('smrd:safeguards-specialist:tech-fast', 'safeguards-specialist', 'tech-fast', 1, true, '[{"dim":"systems","change":"adapts","text_en":"Any future fleet would bring its own arrangements, designed and managed outside Kafa''a; this overlay stays at career-path level.","text_ar":"سيأتي أي أسطول مستقبلي بترتيباته الخاصة التي تُصمَّم وتُدار خارج كفاءة؛ وتبقى هذه الطبقة على مستوى المسار المهني."}]'::jsonb, 'Fast reactors with liquid-metal coolant: career-path view only. Security, safeguards and cyber arrangements for any future fleet are designed and managed outside Kafa''a. Planning assumption; no deployment decision implied.', 'المفاعلات السريعة المبرّدة بالمعادن السائلة: عرض على مستوى المسار المهني فقط. تُصمَّم ترتيبات الأمن والضمانات والأمن السيبراني لأي أسطول مستقبلي وتُدار خارج كفاءة. افتراض تخطيطي، ولا يعني ذلك أي قرار بالنشر.', 'Your qualification shows only as qualified or not qualified; no security detail is shown here.', 'يظهر تأهيلك فقط بصفة مؤهَّل أو غير مؤهَّل، ولا تُعرض هنا أي تفاصيل أمنية.', '[]'::jsonb, '[{"kind":"course","ref":"c-fs-smr"},{"kind":"lane","ref":"lane-advanced"}]'::jsonb, '{}'::text[], '[{"id":"ans-smr-wf-2025","label":"ANS Nuclear Newswire · Education and training to support Canadian nuclear workforce development (26 Nov 2025)","url":"https://www.ans.org/news/2025-11-26/article-7471/education-and-training-to-support-canadian-nuclear-workforce-development/","as_of":"2026-10-10"},{"id":"iaea-ng-t-3-10","label":"IAEA NG-T-3.10 · Workforce Planning for New Nuclear Power Programmes (2011)","url":"https://www-pub.iaea.org/MTCD/Publications/PDF/Pub1477_web.pdf","as_of":"2026-10-10"}]'::jsonb, array['SMR-WF','IAEA-WFP']::text[], 'published', true, 1, '2026-10-11', 77, 'p-training-mgr', '2026-10-11T08:00:00Z'),
('smrd:safeguards-specialist:tech-msr', 'safeguards-specialist', 'tech-msr', 2, true, '[{"dim":"systems","change":"adapts","text_en":"Any future fleet would bring its own arrangements, designed and managed outside Kafa''a; this overlay stays at career-path level.","text_ar":"سيأتي أي أسطول مستقبلي بترتيباته الخاصة التي تُصمَّم وتُدار خارج كفاءة؛ وتبقى هذه الطبقة على مستوى المسار المهني."}]'::jsonb, 'Molten salt: career-path view only. Security, safeguards and cyber arrangements for any future fleet are designed and managed outside Kafa''a. Planning assumption; no deployment decision implied.', 'مفاعلات الأملاح المنصهرة: عرض على مستوى المسار المهني فقط. تُصمَّم ترتيبات الأمن والضمانات والأمن السيبراني لأي أسطول مستقبلي وتُدار خارج كفاءة. افتراض تخطيطي، ولا يعني ذلك أي قرار بالنشر.', 'Your qualification shows only as qualified or not qualified; no security detail is shown here.', 'يظهر تأهيلك فقط بصفة مؤهَّل أو غير مؤهَّل، ولا تُعرض هنا أي تفاصيل أمنية.', '[]'::jsonb, '[{"kind":"course","ref":"c-fs-smr"},{"kind":"lane","ref":"lane-advanced"}]'::jsonb, '{}'::text[], '[{"id":"ans-smr-wf-2025","label":"ANS Nuclear Newswire · Education and training to support Canadian nuclear workforce development (26 Nov 2025)","url":"https://www.ans.org/news/2025-11-26/article-7471/education-and-training-to-support-canadian-nuclear-workforce-development/","as_of":"2026-10-10"},{"id":"iaea-ng-t-3-10","label":"IAEA NG-T-3.10 · Workforce Planning for New Nuclear Power Programmes (2011)","url":"https://www-pub.iaea.org/MTCD/Publications/PDF/Pub1477_web.pdf","as_of":"2026-10-10"}]'::jsonb, array['SMR-WF','IAEA-WFP']::text[], 'published', true, 1, '2026-10-11', 78, 'p-training-mgr', '2026-10-11T08:00:00Z'),
('smrd:safeguards-specialist:tech-htgr', 'safeguards-specialist', 'tech-htgr', 3, true, '[{"dim":"systems","change":"adapts","text_en":"Any future fleet would bring its own arrangements, designed and managed outside Kafa''a; this overlay stays at career-path level.","text_ar":"سيأتي أي أسطول مستقبلي بترتيباته الخاصة التي تُصمَّم وتُدار خارج كفاءة؛ وتبقى هذه الطبقة على مستوى المسار المهني."}]'::jsonb, 'High-temperature gas-cooled: career-path view only. Security, safeguards and cyber arrangements for any future fleet are designed and managed outside Kafa''a. Planning assumption; no deployment decision implied.', 'المفاعلات عالية الحرارة المبرّدة بالغاز: عرض على مستوى المسار المهني فقط. تُصمَّم ترتيبات الأمن والضمانات والأمن السيبراني لأي أسطول مستقبلي وتُدار خارج كفاءة. افتراض تخطيطي، ولا يعني ذلك أي قرار بالنشر.', 'Your qualification shows only as qualified or not qualified; no security detail is shown here.', 'يظهر تأهيلك فقط بصفة مؤهَّل أو غير مؤهَّل، ولا تُعرض هنا أي تفاصيل أمنية.', '[]'::jsonb, '[{"kind":"course","ref":"c-fs-smr"},{"kind":"lane","ref":"lane-advanced"}]'::jsonb, '{}'::text[], '[{"id":"ans-smr-wf-2025","label":"ANS Nuclear Newswire · Education and training to support Canadian nuclear workforce development (26 Nov 2025)","url":"https://www.ans.org/news/2025-11-26/article-7471/education-and-training-to-support-canadian-nuclear-workforce-development/","as_of":"2026-10-10"},{"id":"iaea-ng-t-3-10","label":"IAEA NG-T-3.10 · Workforce Planning for New Nuclear Power Programmes (2011)","url":"https://www-pub.iaea.org/MTCD/Publications/PDF/Pub1477_web.pdf","as_of":"2026-10-10"}]'::jsonb, array['SMR-WF','IAEA-WFP']::text[], 'published', true, 1, '2026-10-11', 79, 'p-training-mgr', '2026-10-11T08:00:00Z'),
('smrd:nuclear-training-instructor:tech-bwr', 'nuclear-training-instructor', 'tech-bwr', 1, false, '[{"dim":"multi_module","change":"adapts","text_en":"A fleet of small units means several smaller reactors to run and maintain rather than a few large ones. Training crews to coordinate across several units.","text_ar":"يعني أسطول من الوحدات الصغيرة تشغيل وصيانة عدد من المفاعلات الأصغر بدلاً من عدد قليل من المفاعلات الكبيرة. تدريب الأطقم على التنسيق بين عدة وحدات."},{"dim":"passive_safety","change":"new","text_en":"Small reactor designs put more weight on passive cooling that works for a period without AC power or operator action. New scenarios that teach crews to monitor passive systems.","text_ar":"تعطي تصاميم المفاعلات الصغيرة وزناً أكبر للتبريد الخامل الذي يعمل لفترة دون كهرباء متناوبة أو تدخل من المشغلين. سيناريوهات جديدة تعلّم الأطقم مراقبة الأنظمة الخاملة."},{"dim":"digital_ic","change":"adapts","text_en":"A different digital control platform and alarm philosophy from the APR-1400 digital I&C you know. A new simulator and digital interface to master before you teach it.","text_ar":"منصة تحكم رقمية وفلسفة إنذارات تختلفان عن الأجهزة والتحكم الرقمية في APR-1400 التي تعرفها. محاكٍ وواجهة رقمية جديدان يجب إتقانهما قبل تدريسهما."},{"dim":"systems","change":"new","text_en":"A boiling water reactor makes steam in the reactor itself, so plant systems, water chemistry and radiation zones differ from Barakah''s two-loop APR-1400 units. New plant-systems lessons, rebuilt through the systematic approach to training.","text_ar":"يولّد مفاعل الماء المغلي البخار داخل المفاعل نفسه، فتختلف أنظمة المحطة وكيمياء الماء ومناطق الإشعاع عن وحدات APR-1400 ذات الدائرتين في براكة. دروس جديدة لأنظمة المحطة يُعاد بناؤها بالنهج المنهجي للتدريب."}]'::jsonb, 'Small boiling water reactor: the biggest shifts for this role are passive safety and plant systems, coolant and fuel; multi-module operation and digital I&C adapt. Planning assumption; no deployment decision implied.', 'مفاعل الماء المغلي الصغير: أكبر التحولات لهذا الدور في السلامة الخاملة، وأنظمة المحطة والمبرد والوقود، بينما يتكيف كل من التشغيل متعدد الوحدات، والأجهزة والتحكم الرقمية. افتراض تخطيطي، ولا يعني ذلك أي قرار بالنشر.', 'The systematic approach to training, evaluation standards and instructor qualification stay the same.', 'يبقى النهج المنهجي للتدريب ومعايير التقييم وتأهيل المدربين كما هي.', '[{"skill_id":"sk-fs-adv-smr","level":2},{"skill_id":"sk-fs-adv-multimodule","level":1},{"skill_id":"sk-fs-adv-passive","level":2},{"skill_id":"sk-fs-dp-dic","level":1}]'::jsonb, '[{"kind":"microcred","ref":"MC-SMR-FOUND"},{"kind":"course","ref":"c-fs-smr"},{"kind":"pathway","ref":"pw-adv-smr-l1"},{"kind":"course","ref":"c-fs-passive"},{"kind":"pathway","ref":"pw-adv-passive-l1"},{"kind":"pathway","ref":"pw-dp-dic-l1"},{"kind":"pathway","ref":"pw-adv-multimodule-l1"},{"kind":"lane","ref":"lane-advanced"}]'::jsonb, array['fr-adv-instructor']::text[], '[{"id":"ans-smr-wf-2025","label":"ANS Nuclear Newswire · Education and training to support Canadian nuclear workforce development (26 Nov 2025)","url":"https://www.ans.org/news/2025-11-26/article-7471/education-and-training-to-support-canadian-nuclear-workforce-development/","as_of":"2026-10-10"},{"id":"iaea-ng-t-3-10","label":"IAEA NG-T-3.10 · Workforce Planning for New Nuclear Power Programmes (2011)","url":"https://www-pub.iaea.org/MTCD/Publications/PDF/Pub1477_web.pdf","as_of":"2026-10-10"},{"id":"gevh-smr-centre-2025","label":"GE Vernova · GE Vernova Hitachi SMR engineering and service centre, Ontario (June 2025)","url":"https://www.gevernova.com/news/press-releases/ge-vernova-hitachi-nuclear-energy-canada-small-modular-reactor-engineering-service-centre-ontario","as_of":"2026-10-10"}]'::jsonb, array['SMR-WF','IAEA-WFP']::text[], 'published', true, 1, '2026-10-11', 80, 'p-training-mgr', '2026-10-11T08:00:00Z'),
('smrd:nuclear-training-instructor:tech-micro', 'nuclear-training-instructor', 'tech-micro', 2, false, '[{"dim":"multi_module","change":"adapts","text_en":"Many small transportable units rather than one plant. Training crews to coordinate across several units.","text_ar":"وحدات صغيرة كثيرة قابلة للنقل بدلاً من محطة واحدة. تدريب الأطقم على التنسيق بين عدة وحدات."},{"dim":"passive_safety","change":"new","text_en":"Microreactor concepts are designed to cool themselves passively for long periods. New scenarios that teach crews to monitor passive systems.","text_ar":"صُممت مفاهيم المفاعلات المتناهية الصغر لتبريد نفسها بطريقة خاملة لفترات طويلة. سيناريوهات جديدة تعلّم الأطقم مراقبة الأنظمة الخاملة."},{"dim":"digital_ic","change":"new","text_en":"Remote and autonomous operation concepts: monitoring from a distance rather than from a local control room. A new simulator and digital interface to master before you teach it.","text_ar":"مفاهيم التشغيل عن بعد والتشغيل الذاتي: المراقبة من بعيد بدلاً من غرفة تحكم محلية. محاكٍ وواجهة رقمية جديدان يجب إتقانهما قبل تدريسهما."},{"dim":"systems","change":"adapts","text_en":"Compact designs with their own coolant and fuel choices. New plant-systems lessons, rebuilt through the systematic approach to training.","text_ar":"تصاميم مدمجة لها خياراتها الخاصة من المبرد والوقود. دروس جديدة لأنظمة المحطة يُعاد بناؤها بالنهج المنهجي للتدريب."}]'::jsonb, 'Microreactors: the biggest shifts for this role are passive safety and digital I&C; multi-module operation and plant systems, coolant and fuel adapt. Planning assumption; no deployment decision implied.', 'المفاعلات المتناهية الصغر: أكبر التحولات لهذا الدور في السلامة الخاملة، والأجهزة والتحكم الرقمية، بينما يتكيف كل من التشغيل متعدد الوحدات، وأنظمة المحطة والمبرد والوقود. افتراض تخطيطي، ولا يعني ذلك أي قرار بالنشر.', 'The systematic approach to training, evaluation standards and instructor qualification stay the same.', 'يبقى النهج المنهجي للتدريب ومعايير التقييم وتأهيل المدربين كما هي.', '[{"skill_id":"sk-fs-adv-smr","level":2},{"skill_id":"sk-fs-adv-multimodule","level":1},{"skill_id":"sk-fs-adv-passive","level":2},{"skill_id":"sk-fs-dp-dic","level":2},{"skill_id":"sk-fs-adv-micro","level":1}]'::jsonb, '[{"kind":"microcred","ref":"MC-SMR-FOUND"},{"kind":"course","ref":"c-fs-smr"},{"kind":"pathway","ref":"pw-adv-smr-l1"},{"kind":"course","ref":"c-fs-passive"},{"kind":"pathway","ref":"pw-adv-passive-l1"},{"kind":"pathway","ref":"pw-adv-micro-l1"},{"kind":"course","ref":"c-fs-remote"},{"kind":"pathway","ref":"pw-dp-dic-l1"}]'::jsonb, array['fr-adv-instructor']::text[], '[{"id":"ans-smr-wf-2025","label":"ANS Nuclear Newswire · Education and training to support Canadian nuclear workforce development (26 Nov 2025)","url":"https://www.ans.org/news/2025-11-26/article-7471/education-and-training-to-support-canadian-nuclear-workforce-development/","as_of":"2026-10-10"},{"id":"iaea-ng-t-3-10","label":"IAEA NG-T-3.10 · Workforce Planning for New Nuclear Power Programmes (2011)","url":"https://www-pub.iaea.org/MTCD/Publications/PDF/Pub1477_web.pdf","as_of":"2026-10-10"},{"id":"iaea-ai-bulletin","label":"IAEA Bulletin · Enhancing nuclear power production with artificial intelligence (2025)","url":"https://iaea.org/bulletin/enhancing-nuclear-power-production-with-artificial-intelligence","as_of":"2026-10-10"}]'::jsonb, array['SMR-WF','IAEA-WFP']::text[], 'published', true, 1, '2026-10-11', 81, 'p-training-mgr', '2026-10-11T08:00:00Z'),
('smrd:nuclear-training-instructor:tech-htgr', 'nuclear-training-instructor', 'tech-htgr', 3, false, '[{"dim":"multi_module","change":"adapts","text_en":"Several smaller reactor modules may share one plant and one control room. Training crews to coordinate across several units.","text_ar":"قد تتشارك عدة وحدات مفاعل أصغر محطة واحدة وغرفة تحكم واحدة. تدريب الأطقم على التنسيق بين عدة وحدات."},{"dim":"passive_safety","change":"new","text_en":"Gas-cooled designs aim to remove decay heat passively, relying on fuel and materials that tolerate high temperatures. New scenarios that teach crews to monitor passive systems.","text_ar":"تسعى التصاميم المبرّدة بالغاز إلى إزالة حرارة الاضمحلال بطريقة خاملة، معتمدة على وقود ومواد تتحمل درجات حرارة عالية. سيناريوهات جديدة تعلّم الأطقم مراقبة الأنظمة الخاملة."},{"dim":"digital_ic","change":"adapts","text_en":"New digital instrumentation for gas coolant and high-temperature systems. A new simulator and digital interface to master before you teach it.","text_ar":"أجهزة رقمية جديدة لأنظمة التبريد بالغاز والأنظمة عالية الحرارة. محاكٍ وواجهة رقمية جديدان يجب إتقانهما قبل تدريسهما."},{"dim":"systems","change":"new","text_en":"Gas coolant, a different fuel form and high-temperature heat that can also serve industrial processes. New plant-systems lessons, rebuilt through the systematic approach to training.","text_ar":"تبريد بالغاز وشكل وقود مختلف وحرارة عالية يمكن أن تخدم العمليات الصناعية أيضاً. دروس جديدة لأنظمة المحطة يُعاد بناؤها بالنهج المنهجي للتدريب."}]'::jsonb, 'High-temperature gas-cooled: the biggest shifts for this role are passive safety and plant systems, coolant and fuel; multi-module operation and digital I&C adapt. Planning assumption; no deployment decision implied.', 'المفاعلات عالية الحرارة المبرّدة بالغاز: أكبر التحولات لهذا الدور في السلامة الخاملة، وأنظمة المحطة والمبرد والوقود، بينما يتكيف كل من التشغيل متعدد الوحدات، والأجهزة والتحكم الرقمية. افتراض تخطيطي، ولا يعني ذلك أي قرار بالنشر.', 'The systematic approach to training, evaluation standards and instructor qualification stay the same.', 'يبقى النهج المنهجي للتدريب ومعايير التقييم وتأهيل المدربين كما هي.', '[{"skill_id":"sk-fs-adv-smr","level":2},{"skill_id":"sk-fs-adv-multimodule","level":1},{"skill_id":"sk-fs-adv-passive","level":2},{"skill_id":"sk-fs-dp-dic","level":1}]'::jsonb, '[{"kind":"microcred","ref":"MC-SMR-FOUND"},{"kind":"course","ref":"c-fs-smr"},{"kind":"pathway","ref":"pw-adv-smr-l1"},{"kind":"course","ref":"c-fs-passive"},{"kind":"pathway","ref":"pw-adv-passive-l1"},{"kind":"pathway","ref":"pw-dp-dic-l1"},{"kind":"pathway","ref":"pw-adv-multimodule-l1"},{"kind":"lane","ref":"lane-hydrogen"}]'::jsonb, array['fr-adv-instructor']::text[], '[{"id":"ans-smr-wf-2025","label":"ANS Nuclear Newswire · Education and training to support Canadian nuclear workforce development (26 Nov 2025)","url":"https://www.ans.org/news/2025-11-26/article-7471/education-and-training-to-support-canadian-nuclear-workforce-development/","as_of":"2026-10-10"},{"id":"iaea-ng-t-3-10","label":"IAEA NG-T-3.10 · Workforce Planning for New Nuclear Power Programmes (2011)","url":"https://www-pub.iaea.org/MTCD/Publications/PDF/Pub1477_web.pdf","as_of":"2026-10-10"}]'::jsonb, array['SMR-WF','IAEA-WFP']::text[], 'published', true, 1, '2026-10-11', 82, 'p-training-mgr', '2026-10-11T08:00:00Z'),
('smrd:procurement-engineer:tech-intl', 'procurement-engineer', 'tech-intl', 1, false, '[{"dim":"digital_ic","change":"adapts","text_en":"Different digital platforms and engineering tools from each partner. Digital procurement and obsolescence management for new platforms.","text_ar":"منصات رقمية وأدوات هندسية مختلفة لدى كل شريك. المشتريات الرقمية وإدارة التقادم للمنصات الجديدة."},{"dim":"delivery","change":"new","text_en":"Project delivery abroad, investment and owner''s-engineer work for partners. International partners, contracts and owner''s-engineer support.","text_ar":"تنفيذ المشاريع في الخارج والاستثمار وأعمال مهندس المالك للشركاء. شركاء دوليون وعقود ودعم مهندس المالك."}]'::jsonb, 'International projects: the biggest shifts for this role are project delivery; digital I&C adapts. Planning assumption; no deployment decision implied.', 'المشاريع الدولية: أكبر التحولات لهذا الدور في تنفيذ المشاريع، بينما يتكيف كل من الأجهزة والتحكم الرقمية. افتراض تخطيطي، ولا يعني ذلك أي قرار بالنشر.', 'Nuclear procurement discipline, commercial-grade dedication and vigilance against counterfeit items stay the same.', 'يبقى انضباط المشتريات النووية والتأهيل التجاري واليقظة تجاه المواد المزيفة كما هي.', '[{"skill_id":"sk-fs-adv-smr","level":1},{"skill_id":"sk-fs-dp-dic","level":1},{"skill_id":"sk-en-01-project","level":1}]'::jsonb, '[{"kind":"microcred","ref":"MC-SMR-FOUND"},{"kind":"course","ref":"c-fs-smr-x"},{"kind":"pathway","ref":"pw-adv-smr-l1"},{"kind":"pathway","ref":"pw-dp-dic-l1"},{"kind":"lane","ref":"lane-advanced"}]'::jsonb, array['fr-owners-engineer']::text[], '[{"id":"ans-smr-wf-2025","label":"ANS Nuclear Newswire · Education and training to support Canadian nuclear workforce development (26 Nov 2025)","url":"https://www.ans.org/news/2025-11-26/article-7471/education-and-training-to-support-canadian-nuclear-workforce-development/","as_of":"2026-10-10"},{"id":"iaea-ng-t-3-10","label":"IAEA NG-T-3.10 · Workforce Planning for New Nuclear Power Programmes (2011)","url":"https://www-pub.iaea.org/MTCD/Publications/PDF/Pub1477_web.pdf","as_of":"2026-10-10"},{"id":"nucleareurope-match","label":"nucleareurope · MATCH programme: a tool for nuclear capacity building in France","url":"https://www.nucleareurope.eu/blog/highlight-of-the-month/match-program-a-tool-for-nuclear-capacity-building-in-france/","as_of":"2026-10-10"},{"id":"saskpolytech-nuclear","label":"Saskatchewan Polytechnic · Nuclear skills training (short, non-credit cross-over courses)","url":"https://saskpolytech.ca/programs-and-courses/part-time-studies/nuclear-skills-training.aspx","as_of":"2026-10-10"}]'::jsonb, array['SMR-WF','IAEA-WFP']::text[], 'published', true, 1, '2026-10-11', 83, 'p-training-mgr', '2026-10-11T08:00:00Z')
